from pathlib import Path
from datetime import datetime,timezone
import base64,zlib,json,hashlib,os,socket,shutil,tempfile,subprocess,fcntl
BUNDLE=''
MARK='# AZMEDNSK osteopathy canonical 20261114'
RULES='''    # AZMEDNSK osteopathy canonical 20261114
    location = /uslugi/osteopatiya { return 301 /osteopaty/$is_args$args; }
    location = /uslugi/osteopatiya/ { return 301 /osteopaty/$is_args$args; }
    location = /uslugi/osteopatiya/index.html { return 301 /osteopaty/$is_args$args; }
'''
def sha(b):return hashlib.sha256(b).hexdigest()
def config_after(old):
 s=old.decode();needle='    location / {'
 if MARK in s:
  assert RULES in s,'STOP: redirect differs';return old
 assert s.count(needle)==1 and 'root /var/www/azmednsk-preview;' in s and 'azmednsk.ru' in s,'STOP: unexpected nginx config'
 assert '/uslugi/osteopatiya' not in s,'STOP: existing old route'
 return s.replace(needle,RULES+needle,1).encode()
def main():
 assert socket.gethostname()=='vdska' and os.geteuid()==0,'STOP: host/user'
 lock=open('/tmp/azmednsk-osteopathy-main.lock','a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 root=Path('/var/www/azmednsk-preview');assert root.is_dir() and not root.is_symlink()
 cfg=Path('/etc/nginx/sites-enabled/azmednsk-preview').resolve();assert str(cfg)=='/etc/nginx/sites-available/azmednsk-preview'
 payload=json.loads(zlib.decompress(base64.b64decode(BUNDLE)));oldcfg=cfg.read_bytes();newcfg=config_after(oldcfg)
 def target(k):
  p=root/k;assert not Path(k).is_absolute() and '..' not in Path(k).parts
  assert p.resolve().is_relative_to(root.resolve()) and all(not x.is_symlink() for x in [p,*p.parents]),'STOP: symlink'
  return p
 guards={k:target(k).read_bytes() for k in payload['guards']};assert all(sha(b)==payload['guards'][k] for k,b in guards.items()),'STOP: collage page changed'
 preview=target('team-2/index.html').read_bytes()
 writes={};before={}
 for k,v in payload['changes'].items():
  p=target(k);b=p.read_bytes();new=v['content'].encode();assert sha(new)==v['after']
  if sha(b)==v['after']:continue
  assert sha(b)==v['before'],'STOP: changed file '+k
  writes[p]=new;before[p]=b
 if oldcfg!=newcfg:writes[cfg]=newcfg;before[cfg]=oldcfg
 if not writes:print('ALREADY_APPLIED=PASS');return
 subprocess.run(['nginx','-t'],check=True,capture_output=True)
 backup=Path('/var/backups/azmednsk')/('osteopathy-main-'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'));backup.mkdir(parents=True)
 for p,b in before.items():
  dest=backup/('nginx.conf' if p==cfg else str(p.relative_to(root)));dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dest);assert dest.read_bytes()==b
 print('PREFLIGHT=PASS; LINKS=9_PAGES; TEAM_TEXT=INCLUDED; COLLAGE=UNCHANGED',flush=True)
 def atomic(p,data):
  fd,tmp=tempfile.mkstemp(dir=p.parent,prefix='.az-osteopathy-')
  try:
   with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
   shutil.copystat(p,tmp);st=p.stat();os.chown(tmp,st.st_uid,st.st_gid);os.replace(tmp,p)
  finally:
   if os.path.exists(tmp):os.unlink(tmp)
 done=[]
 try:
  for p,b in writes.items():
   assert p.read_bytes()==before[p],'STOP: concurrent change';atomic(p,b);done.append(p)
  subprocess.run(['nginx','-t'],check=True,capture_output=True)
  subprocess.run(['systemctl','reload','nginx'],check=True,capture_output=True)
  assert all(p.read_bytes()==b for p,b in writes.items())
  assert all(target(k).read_bytes()==b for k,b in guards.items()) and target('team-2/index.html').read_bytes()==preview
 except BaseException:
  for p in reversed(done):
   if p.read_bytes()==writes[p]:atomic(p,before[p])
  subprocess.run(['nginx','-t'],check=True,capture_output=True);subprocess.run(['systemctl','reload','nginx'],check=True,capture_output=True)
  print('ROLLBACK=PASS; BACKUP='+str(backup));raise
 print('OSTEOPATY_MAIN=PASS; OLD_URL=301; SITEMAP=UPDATED; TEAM_TEXT=PASS; PHOTOS=UNCHANGED')
 print('BACKUP='+str(backup));print('URL=https://azmednsk.ru/osteopaty/');print('TEAM_URL=https://azmednsk.ru/team/#osteopathy')
if __name__=='__main__':
 try:main()
 except Exception as e:raise SystemExit(str(e))
